use genex::prelude::*;
use genex::render::Decal;

/// A surface's three maps from one CC0 set: colour, relief (OpenGL normal) and roughness/metal (glTF packing).
fn surface(set: &str, relief: f32) -> Material {
    Material::color(Color::WHITE)
        .with_base_texture(&format!("cc0/{set}/color.jpg"))
        .with_normal_texture(&format!("cc0/{set}/normal_gl.jpg"), relief)
        .with_metal_rough_texture(&format!("cc0/{set}/arm.jpg"))
}

/// Wet tile reads glossy where a puddle lies: a ground decal, not a darker material.
fn draw_puddle(frame: &mut Frame, at: Vec3) {
    frame.tag("puddle");
    frame.decal(
        &Decal::on_ground(at, 1.4, 0.9)
            .with_base_texture("decals/puddle.png")
            .with_color(Color::rgb(40, 42, 46))
            .with_roughness(0.04)
            .with_flatten(1.0),
    );
}
